      "تتعدد تطبيقات الرخصة في الشريعة لتشمل التيمم، والمسح على الخفين، والصلاة قعوداً للمريض، وإفطار المسافر والمريض في رمضان.",
      "تعد قاعدة 'المشقة تجلب التيسير' من القواعد الفقهية الأساسية المستنبطة من قوله تعالى: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ [البقرة: ١٨٥].",
