      "المحرمات بالقرابة أربعة أصناف هنّ: الأمهات، البنات، الأخوات وبناتهن وبنات الإخوة، والعمات والخالات، بينما يجوز الزواج ببنات العمات والخالات.",
      "يتحقق التحريم بالمصاهرة بمجرد العقد في حالات أم الزوجة وزوجة الأب وزوجة الابن، بينما يشترط الدخول بالزوجة لتحريم ابنتها (الربيبة) لقوله تعالى: ﴿وَرَبَٰٓئِبُكُمُ ٱلَّتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّتِي دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُواْ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ﴾ [الن…",
      "يثبت التحريم بالرضاع بخمس رضعات متفرقات في العامين الأولين من عمر الطفل، ويحرم من الرضاع ما يحرم من النسب لقوله ﷺ: «يَحْرُمُ مِنَ الرَّضَاعِ مَا يَحْرُمُ مِنَ النَّسَبِ».",
      "التحريم المؤقت يزول بزوال السبب العارض، ومن أمثلته تحريم الجمع بين الأختين لقوله تعالى: ﴿وَأَن تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ ۗ إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا﴾ [النساء: ٢٣]، والجمع بين المرأة وعمتها أو خالتها.",
      "تتمثل الحكمة من تحريم الزواج ببعض الأقارب في تنظيم العلاقات الأسرية، ومنع النزاع، وضمان إنجاب نسل قوي خالٍ من الأمراض الوراثية."
