    "summary": "يبدأ الدرس بتعريف التعايش الإنساني بأنه احترام الآخرين على اختلاف معتقداتهم وأعراقهم وثقافاتهم، والتعامل معهم بالعدل والإحسان وفق مبادئ الشريعة الإسلامية. ويؤسس الإسلام هذا التعايش على خمسة مبادئ رئيسية هي: وحدة الأصل البشري كما في قوله تعالى: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً﴾ [النساء: ١]، والكرامة الإنسانية المقررة في قوله تعالى: ﴿وَلَقَدْ كَرَّمْنَا بَنِيٓ ءَادَمَ﴾ [الإسراء: ٧٠]، والعدالة المطلقة مع الجميع لقوله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُواْ ۚ ٱعْدِلُواْ هُوَ أَقْرَبُ لِلتَّقْوَىٰ﴾ [المائدة: ٨]، بالإضافة إلى الحوار بالحسنى والبر والإحسان لغير المعتدين.\n\nوينتقل الدرس لتفصيل مجالات التعايش؛ فالديني يكفل حرية الاعتقاد لقوله تعالى: ﴿لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾ [الكافرون: ٦]، والاجتماعي يدعو للتكافل والمشاركة الإنسانية لقوله تعالى: ﴿يَٰأَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لتَعَارَفُوا﴾ [الحجرات: ١٣]، والاقتصادي يبيح التعامل المالي مع غير المسلمين، والسياسي يرسخ حق المواطنة كما في وثيقة المدينة المنورة والعهدة العمرية، وأخيراً التعايش الدولي القائم على السلم والمعاملة بالمثل. ويختتم الدرس بإبراز جهود المملكة الأردنية الهاشمية وجلالة الملك عبد الله الثاني في تعزيز الوئام بين الأديان وإطلاق المبادرات العالمية الداعية للتسامح والعيش المشترك.",
    "keyPoints": [
      "التعايش الإنساني يقوم على احترام الاختلاف والتعامل بالعدل والإحسان وفق أحكام الشريعة الإسلامية.",
      "يرتكز التعايش في الإسلام على مبادئ ثابتة كالأصل البشري الواحد، والكرامة الإنسانية، والعدالة، والحوار بالحسنى، والبر والإحسان لقوله تعالى: ﴿لَا يَنْهَكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَارِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ…",
      "تتعدد مجالات التعايش لتشمل الجوانب الدينية، والاجتماعية، والاقتصادية (كوفاة النبي ﷺ ودرعه مرهونة عند يهودي)، والسياسية، والدولية.",
      "تعد وثيقة المدينة المنورة والعهدة العمرية من أبرز النماذج التاريخية التي كفلت حقوق المواطنة وحرية الاعتقاد لغير المسلمين.",
      "يبرز دور الأردن الريادي في نشر التعايش من خلال رسالة عمان، والوصاية الهاشمية على المقدسات، ومبادرة أسبوع الوئام العالمي بين الأديان."
    ],
