      "بيان الأعمال الثلاثة التي يرضاها الله تعالى: توحيد الله وعبادته، والاعتصام بحبل الله والوحدة، ومناصحة ولاة الأمور.",
      "التحذير من الكلام غير النافع (اللغو) وتجنب الخوض في 'قيل وقال' حمايةً للمجتمع.",
      "النهي الشديد عن إضاعة المال وصوره المتمثلة في التبذير، والإسراف، وكنز المال دون استثمار.",
      "التمييز بين السؤال المنهي عنه (كثرة السؤال بلا فائدة) والسؤال المأمور به لطلب العلم والمعرفة."
